function clean(value) { return value.replace(/\s+([،؟,.])/g, "$1").replace(/\s{2,}/g, " ").trim(); }
function translatePhrase(value) {
  const exact = phraseMap.find(([from]) => from === value)?.[1];
  if (exact) return clean(exact);
  let result = (exact ?? value).replaceAll("gMSA", "__GMSA_TOKEN__");
  if (!exact) for (const [from, to] of phraseMap) result = result.replaceAll(from, to);
  result = result.replaceAll("__GMSA_TOKEN__", "gMSA");
  const tokens = result.match(/[A-Za-z][A-Za-z0-9'./:_-]*|\d+|[^A-Za-z0-9]+/g) ?? [];
  return clean(tokens.map((token) => {
    if (!/^[A-Za-z]/.test(token)) return token;
    const match = token.match(/^([A-Za-z][A-Za-z0-9'/_:-]*)([.,])?$/);
    const bare = match?.[1] ?? token;
    const suffix = match?.[2] ?? "";
    if (technical.test(bare)) return `(${bare})${suffix}`;
    return `${words[bare] ?? words[bare.toLowerCase()] ?? `(${bare})`}${suffix}`;
  }).join(""));
}

function translateOption(value) {
  const exact = phraseMap.find(([from]) => from === value)?.[1];
  if (exact) return exact;
  if (/^(?:[A-Za-z]:\\|(?:Get|Set|Test|New|Add|Remove|Install|Enable|Disable|Resolve|Convert|Invoke|netdom|dcdiag|repadmin|tracert|nslookup)\b.*|.*(?:\.sys|\.efi|\.dit|\.com|\.org|:|\/|\\).*)$/.test(value)) return `فرمان «${value}»`;
  const translated = translatePhrase(value);
  return translated || `گزینهٔ «${value}»`;
}

function translateQuestion(value) {
  const exact = phraseMap.find(([from]) => from === value)?.[1];
  if (exact) return `${clean(exact).replace(/[?؟]\s*$/, "")}؟`;
  const result = translatePhrase(value).replace(/[?؟]\s*$/, "");
  const alreadyQuestion = result.includes("چیست") || result.endsWith("می‌شود") || result.includes("برای چه کاری") || result.includes("طراحی شده است") || result.includes("برای دستیابی به چه هدفی");
  return `${/^What is\b/i.test(value) && !alreadyQuestion ? `${result} چیست` : result}؟`;
}

