  const lead = text.startsWith("چرا") ? "این گزینه علت درست رفتار مطرح‌شده را توضیح می‌دهد" : text.startsWith("کدام") ? "این گزینه قابلیت یا نقش مورد پرسش را مشخص می‌کند" : "این گزینه اقدام مناسب سناریوی مطرح‌شده را نشان می‌دهد";
  const subject = text.replace(/[؟?]\s*$/, "");
  return `پاسخ درست «${answer}» است؛ ${lead}. در این سناریو، این انتخاب نیاز مطرح‌شده در «${subject}» را برآورده می‌کند. ${rationaleByDomain[question.domain] ?? "این انتخاب با روش توصیه‌شده در راهنمای رسمی AZ-802 سازگار است."}`;
