const lines = source.split(/\r?\n/);
const output = lines.map((line) => {
  if (!line.trim().startsWith("{")) return line;
  const comma = line.endsWith(",") ? "," : "";
  const question = JSON.parse(line.slice(0, line.length - comma.length));
  question.textFa = translateQuestion(question.text);
  question.optionsFa = question.options.map(translateOption);
  question.rationale.fa = rationaleFa(question, translateOption(question.options[question.correct]));
  return JSON.stringify(question) + comma;
});
fs.writeFileSync(path, output.join("\n"));
